#include <algorithm>

using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n;
    if (!(cin >> n)) return 0;

    double min_price = 1e18;

    for (int i = 0; i < n; ++i) {
        double p;
        int g;
        cin >> p >> g;
        double price_per_kg = (p / g) * 1000.0;
        if (price_per_kg < min_price) {
